import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.HurtArmour{Cause: 34, Damage: 200, ArmourSlots: 31}
WITH_SLOTS = bytes.fromhex("4490031f")

# generated by gophertunnel b8bd735:
# &packet.HurtArmour{Cause: -1, Damage: 0, ArmourSlots: 0}
NEGATIVE_CAUSE = bytes.fromhex("010000")

# generated by gophertunnel b8bd735:
# &packet.HurtArmour{Cause: 0, Damage: 0, ArmourSlots: 1}
ONE_SLOT = bytes.fromhex("000001")

GOLDENS = [
    pytest.param(
        v2225.HurtArmorPacket(cause=v2225.ActorDamageCause.MACE_SMASH, dmg=200, armor_slots=31),
        WITH_SLOTS,
        id="mace-smash-with-slots",
    ),
    pytest.param(
        v2225.HurtArmorPacket(cause=v2225.ActorDamageCause.NONE, dmg=0, armor_slots=0),
        NEGATIVE_CAUSE,
        id="negative-cause-is-a-signed-varint",
    ),
    pytest.param(
        v2225.HurtArmorPacket(cause=v2225.ActorDamageCause.OVERRIDE, dmg=0, armor_slots=1),
        ONE_SLOT,
        id="armor-slots-do-not-zigzag",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_hurt_armor_is_packet_38(version):
    assert version.packets[38] is version.HurtArmorPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_hurt_armor_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_hurt_armor_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
